DO $$
BEGIN
    IF EXISTS (
        SELECT 1
        FROM "ai_reports"
        WHERE ("status" = 'COMPLETED' AND "content" IS NULL)
           OR ("status" <> 'COMPLETED' AND ("title" IS NOT NULL OR "content" IS NOT NULL))
    ) THEN
        RAISE EXCEPTION 'ai_reports에 상태와 결과가 맞지 않는 row가 있어 분리할 수 없다';
    END IF;
END $$;

ALTER TABLE "ai_reports" RENAME TO "ai_analyses";
ALTER INDEX IF EXISTS "ai_reports_pkey" RENAME TO "ai_analyses_pkey";
ALTER SEQUENCE IF EXISTS "ai_reports_id_seq" RENAME TO "ai_analyses_id_seq";

CREATE TABLE "ai_reports" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "title" VARCHAR(200),
    "content" TEXT NOT NULL,
    "created_at" TIMESTAMP NOT NULL
);

INSERT INTO "ai_reports" ("id", "title", "content", "created_at")
SELECT "id", "title", "content", "created_at"
FROM "ai_analyses"
WHERE "status" = 'COMPLETED';

SELECT setval(pg_get_serial_sequence('"ai_reports"', 'id'), COALESCE(MAX("id"), 1), MAX("id") IS NOT NULL)
FROM "ai_reports";

ALTER TABLE "ai_analyses" ADD COLUMN "report_id" BIGINT UNIQUE REFERENCES "ai_reports" ("id");

UPDATE "ai_analyses"
SET "report_id" = "id"
WHERE "status" = 'COMPLETED';

ALTER TABLE "ai_analyses" DROP COLUMN "title";
ALTER TABLE "ai_analyses" DROP COLUMN "content";

ALTER TABLE "ai_analyses"
    ALTER COLUMN "upload_expires_at" TYPE TIMESTAMPTZ
    USING "upload_expires_at" AT TIME ZONE 'UTC';
